import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1787821181000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js ≥ 22</li><li>A Healthchecks project and an API key for it. On the hosted service that is Project Settings → API Access; on a self-hosted instance the same page.</li><li>Nothing else. There is no database, no state directory and no port.</li></ul><h2 id="get-an-api-key" tabindex="-1">Get an API key <a class="header-anchor" href="#get-an-api-key" aria-label="Permalink to “Get an API key”">​</a></h2><p>API keys in Healthchecks are <strong>per project, not per account</strong>. A key that works for one project answers <code>403</code> for every check in another, which is the single most common confusion with this API.</p><p>Each project offers two kinds:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Good for</th></tr></thead><tbody><tr><td><strong>Read-only</strong></td><td>Asking questions. On the hosted service it starts with <code>hcr_</code>. Cannot reach ping bodies, integrations or any write tool.</td></tr><tr><td><strong>Read-write</strong></td><td>Everything, including deleting a check.</td></tr></tbody></table><p>Start with a read-only key if you only want to look. Note the asymmetry: three tools that plainly only read — <code>list_pings</code>, <code>get_ping_body</code> and <code>list_integrations</code> — still require a <strong>read-write</strong> key, because that is how the API is gated. <code>get_api_key_info</code> reports which kind you gave it, so you never have to guess from a <code>401</code>.</p><p>Whichever you use, the key is exactly 32 characters. Anything else is answered with <code>401 missing api key</code>, which reads as if no header was sent at all — so this server checks the length itself and says so before spending a request on it.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">HEALTHCHECKS_API_KEY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">…</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> healthchecks-mcp</span></span></code></pre></div><p>Against a self-hosted instance, add the site root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">HEALTHCHECKS_API_KEY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">…</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> HEALTHCHECKS_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://hc.example.net</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> healthchecks-mcp</span></span></code></pre></div><p>That is the <strong>site root</strong>, not the API root — <code>https://hc.example.net</code>, not <code>https://hc.example.net/api/v3</code>. Both are accepted, because the API documentation spells every example the long way and the suffix is trimmed, but the short form is the one to write.</p><p>Without an API key the server still starts and lists its tools, so registries and sandbox inspectors can introspect it. Every call except <code>get_status</code> then fails with setup instructions instead of reaching the API.</p><h2 id="first-calls" tabindex="-1">First calls <a class="header-anchor" href="#first-calls" aria-label="Permalink to “First calls”">​</a></h2><p>Three tools, in the order they are useful when something is wrong:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>get_status          → is the instance reachable at all (no API key needed)</span></span>
<span class="line"><span>list_checks         → which checks exist, and which are down</span></span>
<span class="line"><span>get_ping_body       → what the failing job actually printed</span></span></code></pre></div><p>From there, <a href="/guide/clients">connecting clients</a> covers Claude Code, Claude Desktop, Codex, Docker and mcp-hub, and <a href="/guide/configuration">configuration</a> covers narrowing the tool list before you hand it to a model.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};